function N({registerIndicator:k,sourceValues:y,nulls:g}){k({id:"oa-edcf",name:"EDCF: Ehlers Distance Coefficient Filter",category:"Filters",placement:"onchart",inputs:[{key:"length",type:"number",label:"Length",default:15,min:2,max:50,step:1,tooltip:"Filter window length. Larger = smoother but more lag."},{key:"source",type:"source",label:"Source",default:"hl2"}],plots:[{key:"edcf",type:"line",title:"EDCF",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,u){const o=Math.min(50,Math.max(2,Math.floor(Number(u.length)||15))),n=y(s,u.source||"hl2"),h=s.length,F=2*(o-1),c=new Array(h).fill(NaN);for(let e=0;e<h;e++){const m=n[e];if(e<F){c[e]=m;continue}let r=0,b=0,t=!0;for(let l=0;l<o&&t;l++){const a=n[e-l];if(!Number.isFinite(a)){t=!1;break}let i=0;for(let f=1;f<o;f++){const d=n[e-l-f];if(!Number.isFinite(d)){t=!1;break}const p=a-d;i+=p*p}if(!t)break;r+=i,b+=i*a}c[e]=t&&r!==0?b/r:m}return{edcf:g(c)}}})}export{N as default};
